  "identities": [
    {
      "id": "id_r_su",
      "at": 5,
      "referent": "r_su",
      "entity": "known:c01:ent_su",
      "decision": "same",
      "certainty": "accepted",
      "rationale": "本章第5段起‘苏天晴’持续出现，与第1章已确认的苏天晴同一。",
      "evidence": [
        "d05",
        "known:c01:id_su"
      ]
    },
    {
      "id": "id_r_su_original",
      "at": 5,
      "referent": "r_su_original",
      "entity": "known:c01:ent_original_owner",
      "decision": "same",
      "certainty": "accepted",
      "rationale": "第5段‘原主人的裂屏手机’中的原主人，与第2章已确认的原主人同一；后续‘苏天晴小姐’‘原身’均指该持续对象。",
      "evidence": [
        "d05",
        "known:c02:id_original2"
      ]
    },
    {
      "id": "id_r_wind",
      "at": 16,
      "referent": "r_wind",
      "entity": "known:c02:ent_zhengpai",
      "decision": "same",
      "certainty": "accepted",
      "rationale": "第11段蓉城目前正好有一名活跃魔法少女；第13-16段视频中这名魔法少女，苏天晴念出代号风信子；结合第2章任务目标正牌魔法少女在蓉城，同一持续对象。",
      "evidence": [
        "d11",
        "d12",
        "d13",
        "d15",
        "d16",
        "known:c02:id_genuine2"
      ]
    },
    {
      "id": "id_r_magical_girls",
      "at": 10,
      "referent": "r_magical_girls",
      "entity": "ent_magical_girl_class",
      "decision": "same",
      "certainty": "accepted",
      "rationale": "本章‘魔法少女’作为客观存在的类被反复指称。",
      "evidence": [
        "d04",
        "d10",
        "d11"
      ]
    },
    {
      "id": "id_r_monsters",
      "at": 10,
      "referent": "r_monsters",
      "entity": "ent_monster_class",
      "decision": "same",
      "certainty": "accepted",
      "rationale": "本章‘怪人怪兽’‘怪人’‘怪兽’作为与魔法少女对立的类被指称。",
      "evidence": [
        "d10",
        "d11"
      ]
    },
    {
      "id": "id_r_hero_assoc",
      "at": 10,
      "referent": "r_hero_assoc",
      "entity": "ent_hero_assoc",
      "decision": "same",
      "certainty": "accepted",
      "rationale": "‘英雄协会’作为组织被指称。",
      "evidence": [
        "d11"
      ]
    },
    {
      "id": "id_r_rongcheng",
      "at": 11,
      "referent": "r_rongcheng",
      "entity": "known:c02:ent_rongcheng",
      "decision": "same",
      "certainty": "accepted",
